import redis
r = redis.Redis(host="cache.internal", port=6379)

def add_to_cart(session_id, item):
    r.rpush(f"cart:{session_id}", item)

def get_cart(session_id):
    return r.lrange(f"cart:{session_id}", 0, -1)
